    /// Наибольшее отклонение подогнанной кривой от точек (обе — со сдвигом на медиану), dB; и среднее.
    private func error(_ text: String) -> (worst: Double, mean: Double) {
        let pts = PhonesProfile.graphic(text)
        let e: Eq = PhonesProfile.eq(graphic: pts)
        let bands: [EqBand] = e.bands.compactMap { $0 }
        XCTAssertEqual(bands.count, EqSpec.bands)
        let hz: [Double] = (0..<200).map { 20 * pow(1000, Double($0) / 199) }
        let a: [Double] = hz.map { PhonesFit.interp(pts, $0) }
        let b: [Double] = PhonesFit.curve(bands, hz)
        let mid: Double = a.sorted()[100]
        let d: [Double] = zip(a, b).map { abs($0 - mid - $1) }
        return (d.max() ?? 99, d.reduce(0, +) / Double(d.count))
    }

    func testParse() {
        let pts = PhonesProfile.graphic(PhonesGraphicTests.kz)
        XCTAssertGreaterThan(pts.count, 100)
        XCTAssertEqual(pts[0].hz, 20)
        XCTAssertEqual(pts[0].db, -7.2)
        XCTAssertTrue(PhonesProfile.parse(PhonesGraphicTests.kz).isEmpty, "фильтров в GraphicEQ нет")
        XCTAssertTrue(PhonesProfile.graphic("Preamp: -6 dB\nFilter 1: ON PK Fc 100 Hz Gain 1 dB Q 1").isEmpty)
        XCTAssertEqual(PhonesProfile.name(fromFile: "KZ EDX Pro GraphicEQ.txt"), "KZ EDX Pro")
    }

    func testFit() {
        for t in [PhonesGraphicTests.kz, PhonesGraphicTests.sony] {
            let r = error(t)
            print("GraphicEQ fit: worst \(r.worst) dB, mean \(r.mean) dB")
            XCTAssertLessThan(r.worst, 2.5)
            XCTAssertLessThan(r.mean, 0.6)
        }
    }
}
